"""Licence notice for every generated file that carries limn glyph data: a Modified Version of Quicksand (Latin)
and of NanumSquareRound (Hangul, and the 림 in the Latin data), SIL OFL 1.1.
Kept free of '=' and ';' because tools and audits slice the JSON between the first '=' and the last ';'."""

HEADER = (
    "/* Limn Sans typeface data, generated by tools/{tool}, do not edit.\n"
    " * Copyright 2026 The Limn Sans Project Authors (https://github.com/dartworklabs/limn-sans)\n"
    " * Copyright 2011 The Quicksand Project Authors (https://github.com/andrew-paglinawan/QuicksandFamily),\n"
    " *   with Reserved Font Name \"Quicksand\"\n"
    " * Copyright (c) 2010, NAVER Corporation (https://www.navercorp.com/), with Reserved Font Names\n"
    " *   \"Nanum\" and others as listed in OFL.txt\n"
    " * Modified Version of Quicksand and of NanumSquareRound, licensed under the SIL Open Font License,\n"
    " *   Version 1.1 (see OFL.txt)\n"
    " * SPDX-License-Identifier: OFL-1.1\n"
    " */\n"
)


def header(tool):
    h = HEADER.format(tool=tool)
    assert "=" not in h and ";" not in h
    return h
